import { useEffect, useState, type FormEvent } from 'react'
import { Activity, ArrowDownToLine, ArrowLeft, ArrowRight, Bell, CalendarDays, Camera, Check, ClipboardList, FileVideo2, HeartHandshake, Home, ImagePlus, LogOut, MessageCircle, Plus, Search, Send, ShieldCheck, Sparkles, Star, Users } from 'lucide-react'
import { API_BASE, apiRequest } from './api'
import { describeAuditAction } from './auditActions'
import './App.css'

type Role = 'STAFF' | 'GUARDIAN' | 'ADMIN'
type Tab = 'Overview' | 'Activity log' | 'Weekly & monthly' | 'Goals & ratings' | 'Photos & videos' | 'Family reviews' | 'Messages' | 'Notifications' | 'Audit log' | 'Approval requests'
type Session = { role: Role; username: string; token?: string; demo: boolean }
type Child = { id: string; firstName: string; lastName: string; room?: string }
type ActivityRow = { id: string; title: string; description?: string | null; activityAt: string | Date }
type Plan = { id: string; title: string; description?: string | null; period: 'WEEK' | 'MONTH'; periodStart: string | Date; plannedFor?: string | Date | null; status: 'PLANNED' | 'COMPLETED' | 'CANCELLED' }
type Goal = { id: string; title: string; description?: string | null; status: 'NOT_STARTED' | 'IN_PROGRESS' | 'ACHIEVED' | 'ON_HOLD' }
type Rating = { id: string; category: string; score: number; notes?: string | null; ratedAt: string | Date }
type Media = { id: string; kind: 'IMAGE' | 'VIDEO'; originalName: string; mimeType: string; sizeBytes: number; contentUrl?: string; previewUrl?: string; createdAt: string | Date }
type Review = { id: string; childId: string; rating?: number | null; comment: string; staffResponse?: string | null; staffRespondedAt?: string | Date | null; staffRespondedBy?: { username: string } | null; createdAt: string | Date; author?: { username: string } }
type Notice = { id: string; createdAt: string | Date; review: { rating?: number | null; comment: string; child: Child } }
type Contact = { id: string; username: string; staffProfile?: { firstName: string; lastName: string } | null }
type Conversation = { id: string; admin?: { username: string } | null; staff: { username: string }; peerStaff?: { username: string } | null; lastMessage?: { body: string } | null }
type ChatMessage = { id: string; body: string; senderId: string; createdAt: string | Date; sender: { username: string } }
type AuditEntry = { id: string; method: string; route: string; statusCode: number; occurredAt: string | Date; actor: { username: string; role: Role } }
type AuditPage = { entries: AuditEntry[]; nextCursor: string | null }
type ApprovalRequest = { id: string; username: string; email: string | null; createdAt: string | Date; guardianProfile: { firstName: string; lastName: string } | null }

